import { resetError, useErrorContextValue, useLoaderContextValue } from '@pasarpolis/common-react-hooks'
import { useEffect, useMemo, useRef, useCallback } from 'react'
import { Container } from '../../../../../../components'
import BottomBtn from '../../../../../../components/BottomBtn'
import InfoHeader from '../../../../../../components/InfoHeader'
import ShowSnackbar from '../../../../../../components/ShowNotification'
import TitleEditHeading from '../../../../../../components/TitleEditHeading'
import { AgentColorPallette } from '../../../../../../configs/colorPallete'
import { OFFLINE_FORM_DATA } from '../../../../../../constants/cookies'
import { getOfflineAdditionInfoReqBody } from '../../../../../../helpers/getPackageBody'
import { getFromLocalStorageData } from '../../../../../../helpers/localstorage'
import { CHECK_GOLD } from '../../../../../../images'
import { LANG_STRINGS } from '../../../../../../lang'
import VehicleAttachmentData from '../../../../../CommonContainer/OfflinePolicyContainer/components/VehicleAttachmentData'
import VehicleData from '../../../../../CommonContainer/OfflinePolicyContainer/components/VehicleData'
import VehicleModificationData from '../../../../../CommonContainer/OfflinePolicyContainer/components/VehicleModificationData'
import VehiclePhotoData from '../../../../../CommonContainer/OfflinePolicyContainer/components/VehiclePhotoData'
import { OfflinePolicyDataStyle } from '../../../../../CommonContainer/OfflinePolicyContainer/index.style'
import { useUpdateOfflineQuoteVehicle } from '../../../state/hooks/usePolicyState'
import PolicyHolderMobileEmail from '../components/PolicyHolderMobileEmail'
import { OfflineAdditionalReviewStyle } from './index.style'

function OfflineQuoteAdditionalInfoReviewContainer ({ history, match }) {
  const urlParams = useMemo(() => match?.params || {}, [match])
  const offlineLocalData = useRef(getOfflineAdditionInfoReqBody(getFromLocalStorageData(OFFLINE_FORM_DATA)))
  const [, updateOfflineVehicleReq] = useUpdateOfflineQuoteVehicle()
  const [{ UPDATE_OFFLINE_QUOTE_VEHICLE_LOADER }] = useLoaderContextValue()
  const [{ updateOfflineQuoteVehicleStatus }, dispatchError] = useErrorContextValue()

  useEffect(() => {
    if (updateOfflineQuoteVehicleStatus === 'success') {
      history.push(`/offline/success/${urlParams.quoteId}`)
      dispatchError(resetError({
        updateOfflineQuoteVehicleStatus: undefined
      }))
    } else if (updateOfflineQuoteVehicleStatus) {
      ShowSnackbar.error({
        text: updateOfflineQuoteVehicleStatus,
        visible: true
      })
      dispatchError(resetError({
        updateOfflineQuoteVehicleStatus: undefined
      }))
    }
  }, [
    updateOfflineQuoteVehicleStatus, history, urlParams.quoteId,
    dispatchError
  ])

  const handleEditClick = useCallback(() => {
    history.push(`/offline/quotes/additional/info/${urlParams.quoteId}`)
  }, [history, urlParams.quoteId])

  const handleSaveQuote = useCallback(() => {
    updateOfflineVehicleReq({
      body: {
        ...offlineLocalData.current
      },
      id: urlParams.quoteId
    })
  }, [urlParams, updateOfflineVehicleReq])

  return (
    <Container
      title={LANG_STRINGS.overview}
      loader={UPDATE_OFFLINE_QUOTE_VEHICLE_LOADER}
      hideBottomTabs
    >
      <OfflineAdditionalReviewStyle>
        <InfoHeader
          info={LANG_STRINGS.reviewYourDetailsBeforeSubmit}
          bgColor={AgentColorPallette.black}
        />
        <OfflinePolicyDataStyle>
          <TitleEditHeading
            title={LANG_STRINGS.additionalInfo}
            onEditClick={handleEditClick}
            showEditBtn
          />
          {
            offlineLocalData.current.isManualPolicy && (
              <VehicleData policyData={offlineLocalData.current} />
            )
          }
          <PolicyHolderMobileEmail
            policyData={offlineLocalData.current}
          />
          <VehicleModificationData
            policyData={offlineLocalData.current}
          />
          {
            offlineLocalData.current.images && !!Object.keys(offlineLocalData.current.images).length && (
              <VehiclePhotoData
                policyData={offlineLocalData.current}
              />
            )
          }
          <VehicleAttachmentData
            isManualOrder={offlineLocalData.current.isManualPolicy}
            policyData={offlineLocalData.current}
          />
        </OfflinePolicyDataStyle>
        <ShowSnackbar />
      </OfflineAdditionalReviewStyle>
      <BottomBtn
        title={LANG_STRINGS.save}
        icon={CHECK_GOLD}
        onClick={handleSaveQuote}
      />
    </Container>
  )
}

export default OfflineQuoteAdditionalInfoReviewContainer
